// Process ALL merged leads in one pass (functions defined once — avoids OOM/slowness
// from runOnceForEachItem re-parsing 13KB per lead after a long AI Agent run).
// Fast path: memory/sheet/policy leads (skipAI) → keep engine fields, only add appointments.
// AI path: parse $json.output only when present — never JSON.stringify the whole lead.

const NA_WORDS_C = new Set(("na n a vm voice mail fw fwd forwarded to ringing ring rings rang rng long only short busy line number is unavailable switched off call called failed network error distorted cannot cant hear rej reject rejected rejecting the no nr ne route routes ans answer answering answered beep beeps beeping unattended empty silent engage engaged dialed dialled dialer dailer dial you ve dvm cnbr dnd disconnected unreachable then constant cut cuts hangs hung not connecting issue issues invalid out of coverage area again reg cc crm fixed ndt currently have reach reached hello and pu hu db kept speaking someone else broken huu beeeps nsb navm nadb tone loop disconnecting completed drej fvm dnaa screener ai screen screened screening scr email format sms num checked rejection another on facility available this your sorry client me are did speak clear but responding by").split(/\s+/).filter(Boolean));

const CONTACT_WORD = /(call|callback|call ?back|\bcb\b|\bcbk\b|\bclbk\b|cback|appointment|appt|reach|ring|contact)/i;
const INTENT_PHRASE = /(callback|call ?back|\bcb\b|\bcbk\b|\bclbk\b|cback|appointment|appt|call again|call me|call him|call her|will call|asked to call|ask me to call|wants? a? ?call|ring me|reach me|call on|call at|call by|call next|call after)/i;
const WEEKDAY_ALIASES = [
  { re: /\b(monday|mon)\b/, day: 1 }, { re: /\b(tuesday|tues|tue)\b/, day: 2 },
  { re: /\b(wednesday|weds|wed)\b/, day: 3 }, { re: /\b(thursday|thursd|thurs|thur|thu|thr)\b/, day: 4 },
  { re: /\b(friday|fri)\b/, day: 5 }, { re: /\b(saturday|sat)\b/, day: 6 }, { re: /\b(sunday|sun)\b/, day: 0 }
];
const RE_DAY_AFTER = /\b(day after tomorrow|day after tmrw|day after tmr|day after 2moro|dayafter)\b/;
const RE_TOMORROW = /\b(tomorrow|tomorow|tommorow|tommorrow|tomorrw|tomr|tomrw|tmrw|tmrrw|tmrow|tmro|tmr|tmw|tomo|tomm|2moro|2mrw|2morrow|next day|nxt day)\b/;
const RE_TODAY = /\b(today|tonight|tdy|2day|2nite|tonite)\b/;
const RE_NEXT_WEEK = /\b(next week|nxt week|next wk|nxt wk|nextweek)\b/;

function parseDateStr(s) {
  let m = s.match(/(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return new Date(+m[1], +m[2] - 1, +m[3]);
  m = s.match(/(\d{1,2})[\/.](\d{1,2})[\/.](\d{4})/);
  if (m) return new Date(+m[3], +m[2] - 1, +m[1]);
  return null;
}
function extractTime(s) {
  if (/\b(noon|midday|mid day)\b/i.test(s)) return "12:00";
  if (/\bmidnight\b/i.test(s)) return "00:00";
  let m = s.match(/(\d{1,2}):(\d{2})\s*(am|pm)?/i);
  if (m) {
    let h = +m[1]; const min = m[2];
    if (m[3]) { const ap = m[3].toLowerCase(); if (ap === "pm" && h < 12) h += 12; if (ap === "am" && h === 12) h = 0; }
    return String(h).padStart(2, "0") + ":" + min;
  }
  m = s.match(/(\d{1,2})\s*(am|pm)\b/i);
  if (m) {
    let h = +m[1]; const ap = m[2].toLowerCase();
    if (ap === "pm" && h < 12) h += 12; if (ap === "am" && h === 12) h = 0;
    return String(h).padStart(2, "0") + ":00";
  }
  return "";
}
function fmt(d) {
  return d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0");
}

function detectAppointment(rawComments) {
  const text = String(rawComments || "")
    .replace(/\u0131/g, "i").replace(/\u0307/g, "")
    .replace(/ş/g, "s").replace(/ğ/g, "g").replace(/ç/g, "c").replace(/ö/g, "o").replace(/ü/g, "u");
  if (!text.trim()) return null;
  // Split entries; merge continuation lines without a date prefix.
  const rough = (text.includes("||") ? text.split("||") : text.split(/\r?\n/)).map(p => p.trim()).filter(Boolean);
  const parts = [];
  for (const p of rough) {
    if (parts.length && !/\d{4}-\d{2}-\d{2}/.test(p) && !/^email\b/i.test(p) && !/^in progress/i.test(p)) {
      parts[parts.length - 1] = parts[parts.length - 1] + " " + p;
    } else parts.push(p);
  }
  let best = null;
  for (const part of parts) {
    const pieces = part.split("|").map(x => x.trim());
    const body = pieces.length >= 3 ? pieces.slice(2).join(" ") : part.replace(/^\d{4}-\d{1,2}-\d{1,2}\s+\d{1,2}:\d{2}\s*[-\u2013\u2014]?\s*/, "");
    const commentDate = parseDateStr(part);
    const base = commentDate || new Date();
    // Require REAL callback intent in the body (not bare "call"/"ring" from dialer logs).
    if (!INTENT_PHRASE.test(body)) continue;
    const lower = body.toLowerCase();
    let apptDate = null;
    // Only treat ISO dates that appear in the BODY after stripping metadata — and only with intent.
    // Do NOT pull the comment's own timestamp as the appointment date.
    const bodyNoMeta = body;
    const allDates = [...bodyNoMeta.matchAll(/(\d{4})-(\d{1,2})-(\d{1,2})/g)].map(mm => new Date(+mm[1], +mm[2] - 1, +mm[3]));
    // Ignore dates equal to the comment metadata date (timestamp false positive).
    const metaKey = commentDate ? fmt(commentDate) : "";
    const futureish = allDates.filter(d => fmt(d) !== metaKey);
    if (futureish.length >= 1) apptDate = futureish[0];
    if (!apptDate) {
      if (RE_DAY_AFTER.test(lower)) { apptDate = new Date(base); apptDate.setDate(base.getDate() + 2); }
      else if (RE_TOMORROW.test(lower)) { apptDate = new Date(base); apptDate.setDate(base.getDate() + 1); }
      else if (RE_TODAY.test(lower)) { apptDate = new Date(base); }
      else if (RE_NEXT_WEEK.test(lower)) { apptDate = new Date(base); apptDate.setDate(base.getDate() + 7); }
      else {
        for (const wa of WEEKDAY_ALIASES) {
          if (wa.re.test(lower)) {
            apptDate = new Date(base);
            let diff = (wa.day - base.getDay() + 7) % 7;
            if (diff === 0) diff = 7;
            apptDate.setDate(base.getDate() + diff);
            break;
          }
        }
      }
    }
    const time = extractTime(body);
    // Must have relative day/weekday/explicit future OR (time + intent). Never metadata-only.
    let qualifies = !!apptDate || !!time;
    if (!qualifies) continue;
    const cand = { commentDate, apptDate, time, raw: body };
    if (!best) best = cand;
    else {
      const bd = best.commentDate ? best.commentDate.getTime() : 0;
      const cd = commentDate ? commentDate.getTime() : 0;
      if (cd >= bd) best = cand;
    }
  }
  if (!best) return null;
  const now = new Date(); now.setHours(0, 0, 0, 0);
  let status, outcome, detail, when;
  if (best.apptDate) {
    const ad = new Date(best.apptDate); ad.setHours(0, 0, 0, 0);
    when = fmt(best.apptDate) + (best.time ? (" " + best.time) : "");
    if (ad.getTime() < now.getTime()) {
      status = "Missed"; outcome = "Missed - follow up immediately"; detail = "Missed (was " + when + ")";
    } else {
      status = "Scheduled"; outcome = "Upcoming - call on " + when; detail = when;
    }
  } else {
    status = "Scheduled"; outcome = "Callback time set - confirm date"; detail = "time " + best.time; when = best.time;
  }
  return { detected: "Yes", status, outcome, detail, when };
}

function apptFields(comments) {
  const a = detectAppointment(comments);
  return a || { detected: "No", status: "No Appointment", outcome: "No Appointment", detail: "", when: "" };
}

function canonStatus(s) {
  const x = String(s || "").trim().toLowerCase().replace(/\s+/g, " ");
  if (!x) return String(s || "").trim();
  if (/no answer/.test(x) && /(5\s*up|5up|5 ?\+|five up)/.test(x)) return "No Answer 5 UP";
  if (/no answer/.test(x)) return "No Answer 1-5";
  if (/(under\s*18|underage|under age|below 18)/.test(x)) return "Under 18";
  if (/(no language|language barrier)/.test(x)) return "No Language";
  if (/invalid country/.test(x)) return "Invalid Country";
  if (/denied reg/.test(x)) return "Denied Registration";
  if (/(wrong (number|no|num|name|email)|wrong number or email|invalid (number|email))/.test(x)) return "Wrong Number or Email";
  if (/no potential/.test(x)) return "No Potential";
  if (/(no interest|not interested)/.test(x)) return "No Interest";
  if (/call again/.test(x)) return "Call Again";
  if (/recall/.test(x)) return "Recall";
  if (/decline/.test(x)) return "Decline";
  return String(s || "").trim();
}

function isNaLineC(text) {
  let t = String(text || "").toLowerCase()
    .replace(/\u0131/g, "i").replace(/\u0307/g, "")
    .replace(/ş/g, "s").replace(/ğ/g, "g").replace(/ç/g, "c").replace(/ö/g, "o").replace(/ü/g, "u")
    .replace(/[^a-z0-9 ]/g, " ");
  if (!t.trim()) return false;
  t = t.replace(/\b\d+(st|nd|rd|th)\b/g, " ").replace(/\b[a-z]\d+\b/g, " ")
    .replace(/\b(x\d+|\d+x|xx\d+|v\d+|\d+)\b/g, " ").replace(/\s+/g, " ").trim();
  if (!t) return false;
  return t.split(" ").every(tok => NA_WORDS_C.has(tok));
}

function naDistinctDays(raw) {
  const segs = String(raw || "").includes("||") ? String(raw).split("||") : String(raw).split(/\r?\n/);
  const days = new Set();
  for (const p of segs) {
    const seg = p.trim(); if (!seg) continue;
    const dm = seg.match(/\d{4}-\d{2}-\d{2}/);
    const pieces = seg.split("|").map(x => x.trim());
    const body = pieces.length >= 3 ? pieces.slice(2).join(" ") : seg.replace(/^\d{4}-\d{2}-\d{2}\s+\d{1,2}:\d{2}\s*[-\u2013\u2014]?\s*/, "");
    if (isNaLineC(body) && dm) days.add(dm[0]);
  }
  return days.size;
}

function baseLead(j) {
  return {
    brand: j.brand || "",
    "account no": j["account no"] || "",
    "last 10 comments": j["last 10 comments"] || "",
    "customer status": j["customer status"] || j["Customer Status"] || "",
    country: j.country || "",
    Agent: j.Agent || "",
    "Current Agent Office": j["Current Agent Office"] || ""
  };
}

function withAppt(lead, A) {
  return {
    ...lead,
    "Appointment Detected": A.detected,
    "Appointment Status": A.status,
    "When To Call": A.when || A.detail || "",
    "Appointment Detail": A.detail,
    "Appointment Outcome": A.outcome
  };
}

function processItem(j) {
  const original = j;
  const A0 = apptFields(original["last 10 comments"]);

  // FAST PATH — Memory Match / sheet / policy (skipAI): no AI parse, no JSON.stringify
  const isDeterministic = original.skipAI === true || original.memory_matched === true ||
    (original["Suggested Status"] && !original.output && String(original["Decision Source"] || "").indexOf("AI Agent") === -1);

  if (isDeterministic) {
    return { json: withAppt({ ...original }, A0) };
  }

  // AI PATH — only when output string exists
  const raw = original.output || original.text || original.response || original.message || "";
  if (!raw) {
    return { json: withAppt({
      ...baseLead(original),
      "Validation Result": "Manual Check",
      "Suggested Status": original["customer status"] || original["Customer Status"] || "",
      "Reason": "No AI output attached - needs manual review.",
      "Decision Source": original["Decision Source"] || "AI Agent"
    }, A0) };
  }

  let text = String(raw).trim()
    .replace(/^```json\s*/i, "").replace(/^```\s*/i, "").replace(/```$/i, "").trim();
  const fb = text.indexOf("{"), lb = text.lastIndexOf("}");
  if (fb === -1 || lb === -1) {
    return { json: withAppt({
      ...baseLead(original),
      "Validation Result": "Manual Check",
      "Suggested Status": original["customer status"] || "",
      "Reason": "AI output could not be parsed - needs manual review.",
      "Decision Source": "AI Agent"
    }, A0) };
  }
  let parsed;
  try { parsed = JSON.parse(text.slice(fb, lb + 1)); }
  catch (e) {
    return { json: withAppt({
      ...baseLead(original),
      "Validation Result": "Manual Check",
      "Suggested Status": original["customer status"] || "",
      "Reason": "AI JSON parse failed - needs manual review.",
      "Decision Source": "AI Agent"
    }, A0) };
  }

  let finalStatus = canonStatus(parsed["Suggested Status"] || parsed.suggested_status || "");
  let finalReason = parsed["Reason"] || parsed.reason || "";
  if (finalStatus === "No Answer 5 UP") {
    const d = naDistinctDays(original["last 10 comments"]);
    if (d < 5) {
      finalStatus = "No Answer 1-5";
      finalReason = (finalReason ? finalReason + " | " : "") + "Correction: distinct no-answer days=" + d + " (<5) => No Answer 1-5";
    }
  }
  const custRaw = String(original["customer status"] || original["Customer Status"] || "").trim();
  const finalValidation = canonStatus(custRaw).toLowerCase() === canonStatus(finalStatus).toLowerCase() ? "Correct" : "Wrong";
  // Keep more specific CRM subtype when families match (e.g. No Potential - no documents).
  if (finalValidation === "Correct" && custRaw.length > String(finalStatus).trim().length &&
      /no potential/i.test(custRaw) && /no potential/i.test(finalStatus)) {
    finalStatus = custRaw;
  }

  let A = { ...A0 };
  if (A.detected === "No") {
    const aiDet = parsed["Appointment Detected"] || parsed.appointment_detected;
    if (aiDet && String(aiDet).toLowerCase() === "yes") {
      A = {
        detected: "Yes",
        status: parsed["Appointment Status"] || parsed.appointment_status || "Scheduled",
        detail: parsed["Appointment Detail"] || parsed.appointment_detail || "",
        outcome: parsed["Appointment Outcome"] || parsed.appointment_outcome || "",
        when: parsed["Appointment Detail"] || parsed.appointment_detail || ""
      };
    }
  }

  return { json: withAppt({
    ...baseLead(original),
    "Validation Result": finalValidation,
    "Suggested Status": finalStatus,
    "Reason": finalReason,
    "Decision Source": parsed["Decision Source"] || "AI Agent",
    "Matched Sheet Row": parsed["Matched Sheet Row"] || "",
    "Matched Keyword": parsed["Matched Keyword"] || parsed["Rule Trigger"] || ""
  }, A) };
}

return $input.all().map(item => processItem(item.json));

return items.map(item => {
  const j = item.json;

  return {
    json: {
      "brand": j.brand || "",
      "account no": j["account no"] || "",
      "last 10 comments": j["last 10 comments"] || "",
      "customer status": j["customer status"] || "",
      "country": j.country || "",
      "Agent": j.Agent || "",
      "Current Agent Office": j["Current Agent Office"] || ""
    }
  };
});

const inputItems = $input.all();

function normalize(text) {
  return String(text || "")
    .toLowerCase()
    // Fold Turkish characters so agent notes typed with ı/ş/ğ/ç/ö/ü match English rules
    // (e.g. "clıent", "deposıt", "rıngıng", "regıster" -> "client", "deposit", "ringing", "register").
    .replace(/\u0131/g, "i")
    .replace(/\u0307/g, "")
    .replace(/ş/g, "s")
    .replace(/ğ/g, "g")
    .replace(/ç/g, "c")
    .replace(/ö/g, "o")
    .replace(/ü/g, "u")
    .replace(/\\\\n/g, " ")
    .replace(/\\n/g, " ")
    .replace(/\n/g, " ")
    .replace(/\r/g, " ")
    .replace(/\|\|/g, " ")
    .replace(/\|/g, " ")
    // drop apostrophes/quotes so "don't"->"dont", "didn't"->"didnt", "you've"->"youve"
    .replace(/['’`"]/g, "")
    .replace(/[;,.]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function extractCommentParts(rawComments) {
  const raw = String(rawComments || "");
  // Support BOTH comment formats seen in the source files:
  //  - "|| date | agent | text; || date | agent | text;"  (pipe-delimited)
  //  - "date HH:MM - text;\n date HH:MM - text;\n NA"        (newline-delimited)
  // Continuation lines (no date prefix) are MERGED into the previous comment so that
  // "pu - intro ...\nno money - cb tmrw ..." stays one comment with one timestamp.
  const rough = raw.includes("||") ? raw.split("||") : raw.split(/\r?\n/);
  const segments = [];
  const hasDate = s => /\d{4}-\d{2}-\d{2}/.test(s);
  for (const piece of rough) {
    const p = String(piece || "").trim();
    if (!p) continue;
    if (segments.length && !hasDate(p) && !(/^email\b/i.test(p) || /^in progress/i.test(p))) {
      segments[segments.length - 1] = segments[segments.length - 1] + " " + p;
    } else {
      segments.push(p);
    }
  }
  return segments
    .map(part => {
      const dateMatch = part.match(/\d{4}-\d{2}-\d{2}/);
      let commentText;
      if ((part.match(/\|/g) || []).length >= 2) {
        const pieces = part.split("|").map(x => x.trim()).filter(Boolean);
        commentText = pieces.length >= 3 ? pieces.slice(2).join(" ") : part;
      } else {
        commentText = part.replace(/^\d{4}-\d{2}-\d{2}\s+\d{1,2}:\d{2}\s*[-\u2013\u2014]\s*/, "").trim();
        if (!commentText) commentText = part;
      }

      return {
        raw: part,
        date: dateMatch ? dateMatch[0] : "",
        text: commentText,
        normalized: normalize(commentText)
      };
    });
}

function partTimestamp(p) {
  const m = String(p.raw || "").match(/(\d{4})-(\d{2})-(\d{2})\s+(\d{1,2}):(\d{2})/);
  if (m) return Date.UTC(+m[1], +m[2] - 1, +m[3], +m[4], +m[5]);
  return p.date ? Date.parse(p.date + "T12:00:00Z") : 0;
}

// Always newest-first: index 0 = latest comment (|| date | agent | text || format).
function sortPartsNewestFirst(parts) {
  return parts.slice().sort((a, b) => partTimestamp(b) - partTimestamp(a));
}

function isSystemComment(text) {
  // Exclude OUTGOING email subjects ("Email X was sent by ...") and pipeline logs,
  // but DO parse INCOMING customer emails ("INCOMING EMAIL ... am broke no job").
  return /^(email |email\b|missed call email|in progress|new$|duplicate)/i.test(
    String(text || "").trim()
  );
}

// A line is "no-answer only" if, after stripping repeat/count markers (2x, xx2, v2, numbers),
// EVERY remaining token is an unambiguous no-answer / connector word. This recognizes variants
// like "ringing na 2x", "na constant beeping", "long rings only", "rejected the call" that an
// exact-match list would miss. Tight wordlist avoids suppressing real conversations.
const NO_ANSWER_WORDS = new Set([
  "na","n","a","vm","voice","mail","fw","fwd","forwarded","to",
  "ringing","ring","rings","rang","rng","long","only","short","busy","line","number","is",
  "unavailable","switched","off","call","called","failed","network","error","distorted",
  "cannot","cant","hear","rej","reject","rejected","rejecting","the","no","nr","ne",
  "route","routes","ans","answer","answering","answered","beep","beeps","beeping",
  "unattended","empty","silent","engage","engaged","dialed","dialled","dialer","dailer",
  "dial","you","ve","dvm","cnbr","dnd","disconnected","unreachable","then","constant",
  "cut","cuts","hangs","hung","not","connecting",
  // additional no-answer / network-failure variants seen in agent notes
  "issue","issues","invalid","out","of","coverage","area","again","reg","cc","crm",
  "fixed","ndt",
  // telecom "currently busy / number you dialed" rejection lines + no-contact shorthand
  // (pu=picked up, hu=hung up: when ONLY these tokens appear there was no real conversation)
  "currently","have","reach","reached","hello","and","pu","hu","db","kept",
  "speaking","someone","else","broken","huu","beeeps","nsb","navm","nadb",
  "tone","loop","disconnecting","completed",
  // dialer / call-screener shorthand seen in agent notes (no real conversation)
  "drej","fvm","nsb","dnaa","screener","ai","screen","screened","screening","scr",
  // technical invalid-contact / dialer lines treated as no-answer (no real conversation)
  "email","format","sms","num","checked",
  // more telecom / no-contact connector words seen in agent notes
  "rejection","another","on","facility","available","this","your","sorry",
  "client","me","are","did","speak","clear","but","responding","by","voice",
  // concatenated / typo dialer & network-failure variants (still = NO real contact).
  // NOTE: a genuine human pickup (even silent: "pu silent", "pu stayed silent",
  // "pu who are you") is intentionally NOT listed here, so it BREAKS the no-answer streak
  // (the customer was reached) per policy "if they picked up, it is not a clean no-answer run".
  "puhu","narej","rrej","rejj","choppy","choopy","interwined","intertwined",
  "correction","respond","respo","nrespond","norespond","noise","background",
  "drej","ddrej","navm","nadvm","dvms","dvmm","rerej","cb","cbk","clbk","in",
  "dvmo","phone","slots","slot","re","all","db","dbusy","dbx","nadb","rng","rrng"
]);

// Strip ALL punctuation (/, !, -, *, //, etc.) before token check so variants like
// "Ringing // NA !", "Busy//Rejection/NA", "NA - The number...", "Ringing // Rejecting !!"
// are correctly recognized as no-answer-only lines (previously they slipped through and
// were wrongly treated as meaningful conversation, sending the lead to the AI agent).
function isNoAnswerOnlyLine(text) {
  let t = String(text || "")
    .toLowerCase()
    .replace(/\u0131/g, "i").replace(/\u0307/g, "")
    .replace(/ş/g, "s").replace(/ğ/g, "g").replace(/ç/g, "c")
    .replace(/ö/g, "o").replace(/ü/g, "u")
    .replace(/[^a-z0-9 ]/g, " ");
  if (!t.trim()) return false;
  // strip count/repeat markers (2x, xx2), ordinals (5th, 2nd), and short codes (v2, d2, c3)
  t = t
    .replace(/\b\d+(st|nd|rd|th)\b/g, " ")
    .replace(/\b[a-z]\d+\b/g, " ")
    .replace(/\b(x\d+|\d+x|xx\d+|v\d+|\d+)\b/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  if (!t) return false;
  return t.split(" ").every(tok => NO_ANSWER_WORDS.has(tok));
}

// Detects an explicit future callback / appointment / time-promise in a comment line:
// "call me on 5th of july", "give me time", "next week", "tomorrow", day names,
// "i will do it next month", "after 2 hours", "talk to my wife" etc.
function hasFuturePromise(text) {
  const t = normalize(text);
  if (!t) return false;
  // CONCRETE future commitment only (a real date/day/period). Vague phrases like
  // "give me time", "i will contact back", "call me after 2 hours" are NOT enough -
  // those stay as the underlying status (e.g. No Potential when there is no money).
  return /\b(tomorrow|tmrw|next (week|month)|monday|tuesday|wednesday|thursday|friday|saturday|sunday|(till|on|by|next) (mon|tue|tues|wed|weds|thu|thur|thurs|fri|sat|sun)|\d{1,2} ?(st|nd|rd|th)( of)? (jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*|(in|next|by|on) (january|february|march|april|may|june|july|august|september|october|november|december)|after \d+ ?(day|days|week|weeks|month|months))\b/.test(t);
}

// Money / no-financial-ability signal anywhere in the comments.
function hasMoneyIssue(fullComment) {
  return /\b(no funds|dont have funds|do not have funds|no money|dont have (any )?money|no payment (method|option)|cannot afford|cant afford|no income|only (cash|cheque)|no online method|because of funds|no potential)\b/.test(
    normalize(fullComment)
  );
}


// Canonical CRM status family for Correct/Wrong comparison.
// "No Potential - no documents" ≡ "No Potential"; keep more specific sheet status when possible.
function statusCanon(s) {
  const x = String(s || "").trim().toLowerCase().replace(/\s+/g, " ");
  if (!x) return "";
  if (/no answer/.test(x) && /(5\s*up|5up|5 ?\+|five up)/.test(x)) return "no answer 5 up";
  if (/no answer/.test(x)) return "no answer 1-5";
  if (/no potential/.test(x)) return "no potential";
  if (/(wrong (number|no|num|name|email)|wrong number or email)/.test(x)) return "wrong number or email";
  if (/denied reg/.test(x)) return "denied registration";
  if (/(no interest|not interested)/.test(x)) return "no interest";
  if (/no language/.test(x)) return "no language";
  if (/invalid country/.test(x)) return "invalid country";
  if (/under\s*18/.test(x)) return "under 18";
  if (/call again/.test(x)) return "call again";
  if (/recall/.test(x)) return "recall";
  if (/decline/.test(x)) return "decline";
  if (/duplicate/.test(x)) return "duplicate";
  if (/^dnc$/.test(x)) return "dnc";
  return x;
}
function statusEquals(a, b) {
  return statusCanon(a) === statusCanon(b) && statusCanon(a) !== "";
}
// Prefer the more specific of two equivalent statuses (e.g. keep "No Potential - no documents").
function preferSpecificStatus(a, b) {
  const A = String(a || "").trim();
  const B = String(b || "").trim();
  if (!A) return B;
  if (!B) return A;
  if (statusEquals(A, B)) return A.length >= B.length ? A : B;
  return B;
}
// Pickup then busy / lm / not now = real contact, NOT a clean no-answer.
function isBusyAfterPickup(text) {
  const t = normalize(text);
  if (!t) return false;
  return /\b(pu|picked up|pick up)\b/.test(t) &&
    /\b(busy|lm\b|left (a )?message|call (me )?(later|back)|not now|in a meeting|at work|will call|cb\b|callback)\b/.test(t);
}


// Distinct no-answer days in the LATEST uninterrupted streak (resets after real contact).
function countNaStreakDays(parts) {
  const nonSys = parts.filter(p => !isSystemComment(p.text));
  const tsOf = (p) => {
    const m = String(p.raw || "").match(/(\d{4})-(\d{2})-(\d{2})\s+(\d{1,2}):(\d{2})/);
    if (m) return Date.UTC(+m[1], +m[2] - 1, +m[3], +m[4], +m[5]);
    return p.date ? Date.parse(p.date) : 0;
  };
  const nsOrder = nonSys.slice();
  if (nsOrder.length && nsOrder.every(p => tsOf(p))) nsOrder.sort((a, b) => tsOf(b) - tsOf(a));
  let streakContactIdx = -1;
  for (let i = 0; i < nsOrder.length; i++) { if (!isNoAnswerOnlyLine(nsOrder[i].text)) { streakContactIdx = i; break; } }
  const streakSet = new Set();
  const streakEnd = streakContactIdx === -1 ? nsOrder.length : streakContactIdx;
  for (let i = 0; i < streakEnd; i++) { if (isNoAnswerOnlyLine(nsOrder[i].text) && nsOrder[i].date) streakSet.add(nsOrder[i].date); }
  return streakSet.size;
}

function crmCallAgainProtected(crmStatus, naStreakDays) {
  const c = statusCanon(crmStatus);
  return (c === "call again" || c === "recall") && naStreakDays < 5;
}

// Agent CRM status paste in comments — not a client callback intent.
function isAgentStatusNote(text, triggerNorm) {
  const t = String(text || "").trim().toLowerCase().replace(/[^a-z0-9 ]/g, " ").replace(/\s+/g, " ").trim();
  if (triggerNorm === "call again" && (t === "call again" || t === "ca")) return true;
  return false;
}

function hasMeaningfulCustomerConversation(parts) {
  return parts.some(p => {
    if (isSystemComment(p.text)) return false;
    if (isNoAnswerOnlyLine(p.text)) return false;

    const t = p.normalized;

    return t.length >= 12;
  });
}

function countNoAnswerDays(parts) {
  const days = new Set();

  for (const p of parts) {
    if (isNoAnswerOnlyLine(p.text) && p.date) {
      days.add(p.date);
    }
  }

  return days.size;
}

function countTriggerDays(parts, trigger) {
  const days = new Set();

  for (const p of parts) {
    if (p.normalized.includes(trigger) && p.date) {
      days.add(p.date);
    }
  }

  return days.size;
}

function countTriggerOccurrences(parts, trigger, keywordGroup) {
  let count = 0;

  for (const p of parts) {
    if (keywordGroup === "no_answer") {
      if (isNoAnswerOnlyLine(p.text)) count++;
    } else {
      if (p.normalized.includes(trigger)) count++;
    }
  }

  return count;
}

// ---------- POLICY DETECTORS (validated against manual-check spreadsheets) ----------
const FP_RE = /\b(tomorrow|tomorow|tomarrow|2morrow|tmrw|next (week|month|friday|monday|tuesday|wednesday|thursday|saturday|sunday)|monday|tuesday|wednesday|thursday|friday|saturday|sunday|(till|on|by|next) (mon|tue|tues|wed|weds|thu|thur|thurs|fri|sat|sun)|\d{1,2} ?(st|nd|rd|th)( of)? (jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*|(in|next|by|on) (january|february|march|april|may|june|july|august|september|october|november|december)|after \d+ ?(day|days|week|weeks|month|months)|in \d+ ?(day|days|week|weeks|month|months))\b/;
const MONEY_RE = /\b(no money|dont have money|do not have money|havent money|no funds|dont have funds|do not have funds|havent funds|does not have funds|doesnt have funds|dont have the funds|no fund\b|low income|no income|no salary|cant afford|cannot afford|no payment method|no payment option|no other card|debit card only|no online payment|no online method|no bank account|no bank|money in bank|no money in bank|broke|no potential|depends on government|government help|government work|cant pay|cannot pay|no amount|dont have the amount|do not have the amount|dont have any amount|cant do it|cannot do it|cant invest|no money for investment|does not have money|doesnt have money|get money from us|will get money from us)\b/;
const INVESTED_RE = /\b(already invested|invested elsewhere|already have investment|already an investor|invested somewhere|invested with (another|someone)|already paid|paid to|put money (with|in) (another|someone))\b/;
const HEALTH_RE = /\b(deaf|is sick|im sick|i am sick|very sick|seriously ill|paralyzed|paralysed|blind|kidney stone|disabled|extremely old|bed ridden|bedridden|dementia|alzheimer)\b/;
const ARRANGE_RE = /\b(cb\b|cbk\b|clbk\b|cback|cb tmrw|cb tomorrow|callback|give me (some )?time|need (some |a |few )?(time|more time|day|days|week|weeks|month)|i need (a|some|few|more|time)|find something|i will find|call me (back|after|later|on|tomorrow|tomorow|next|in)|call (me )?back|call back (after|at|on|tomorrow|tomorow|later|next|in)|call back later|callback|cb (after|on|at|tomorrow|tomorow|next|later|in)|deblock cb|get back to|i will (arrange|do it|proceed|invest|deposit|check)|will (arrange|do it|proceed|deposit|check)|do it (later|next|tomorrow)|sort it|manage it|will manage|deposit later|visit the bank|get the upi|follow up (tomorrow|tomorow|next|later|by)|told me to call|asked for a cb|cb after|cb at|call later|asked for call|call him later|call her later)\b/;
const TIME_RE = /\b(at \d{1,2} ?(h00|h0|h|:00|am|pm)|after \d{1,2} ?(am|pm)|back (after|at) \d|by \d{1,2} ?(am|pm)|\d{1,2} ?pm|\d{1,2} ?am)\b/;
const EMAILC_RE = /\b(check (the )?email|via (the )?(email|mail|whatsapp)|through (the )?(email|mail|whatsapp)|email me|look at (the )?email|send (it )?to (my )?email|send me (the )?(email|number|your number)|send me your (number|email)|prefer email|over email|communicate.{0,25}(email|whatsapp|mail)|contact.{0,25}(email|whatsapp|mail)|wants? email|reply.{0,15}(email|mail)|reply to (the )?mail|email or whatsapp|on whatsapp|welcome email|will check the steps|check the steps)\b/;
const DEFER_RE = /\b(won?t be doing it now|won?t be doing|will not be doing|not be doing it now|not doing it now|won?t do it now|wont do it now|i won?t be|i won?t do)\b/;
const CURSE_RE = /\b(cursed|curse|curses|abused|abusive|abuse|swore|swear|swearing|insult|insulted|called me 419|419|son of)\b/;
const STRONG_RE = /\b(not interested|no interest|not inter[a-z]{1,6}ed|no inter[a-z]{1,6}ed|not intrested|no intrested|not intres?ted|(dont want|do not want|doesnt want|does not want)(?! to (awake|wake|disturb|bother|annoy|trouble))|not willing|dont wanna|wanna cancel|want to cancel|wants to cancel|to cancel it|cancel it|cancel the|cancel my|please cancel|cancel pls|wanted to cancel|wanted to end|wanna end the call|want to end the call|wanted to end the call|end the call rn|too good to be true|reject it|its not real|not real|scammed|fell for|scammer|scammers|mock[a-z]{0,4}|its a scam|it is a scam|this is a scam|these are scam|are scam|is a scam|all of these are scam|scam and|deep ?fake|fake video|fake videos|lost money before|lost money|invested before and lost|making fun|make fun|fun of|money back|refund|taken my|fed up|waste of time|fraud|does not want to do|doesnt want to do|not want to do|do not want to do|does not want to proceed|does not want to continue|does not want to invest|does not want to register|cant continue|only wanted to know|stop calling|dont call|do not call|leave me alone)\b/;
const FAKEREG_RE = /\b(fake names?|fake naame|fake account|fake profile|fake registration|fake reg\b|fake details|fake info|junk name|gibberish name|garbage name|nonsense name|random name|invalid name|abusive (language )?name|name (is )?(fake|abusive))\b/;
const SOFT_RE = /\b(why are you calling|why you are calling|why are we calling|why we are calling|why are you disturbing|shouting|scold|scolded|annoyed|already associated|associated to someone|associated with someone|kept repeating)\b/;

// Count DISTINCT days with ANY refusal signal (cross-trigger).
// Used for rejection repeat_logic: 1st day => Recall, 2+ different days => No Interest.
// Unlike countTriggerDays (same phrase only), this catches e.g. day1 "not interested" + day2 "stop calling".
function countRefusalDays(parts, rulesList) {
  const days = new Set();
  for (const p of parts) {
    if (!p.date || isSystemComment(p.text)) continue;
    if (lineHasRefusal(p, rulesList)) days.add(p.date);
  }
  return days.size;
}

function lineHasRefusal(p, rulesList) {
  const n = p.normalized;
  if (isNoAnswerOnlyLine(p.text) && !STRONG_RE.test(n) && !SOFT_RE.test(n)) return false;
  if (isTrivialLine(p.text) && !STRONG_RE.test(n) && !SOFT_RE.test(n)) return false;
  if (STRONG_RE.test(n) || SOFT_RE.test(n)) return true;
  for (const r of rulesList) {
    if (String(r.keyword_group || "").toLowerCase().trim() !== "rejection") continue;
    if (String(r.active || "").toLowerCase() === "false") continue;
    const t = normalize(r.trigger_phrase || "");
    if (t.length >= 3 && n.includes(t)) return true;
  }
  return false;
}

// After the FIRST recall/refusal day: count distinct na/vm-only days (no real talk in between).
// 3+ such days => No Interest. Real conversation or a second refusal resets (other rules apply).
function countNaDaysAfterFirstRefusal(parts, rulesList) {
  const asc = sortPartsNewestFirst(parts).slice().reverse();
  let afterRefusal = false;
  const naDays = new Set();
  for (const p of asc) {
    if (!p.date || isSystemComment(p.text)) continue;
    if (!afterRefusal) {
      if (lineHasRefusal(p, rulesList)) afterRefusal = true;
      continue;
    }
    if (lineHasRefusal(p, rulesList)) return 0;
    if (!isNoAnswerOnlyLine(p.text) && contentWordCount(p.text) >= 2) return 0;
    if (isNoAnswerOnlyLine(p.text)) naDays.add(p.date);
  }
  return naDays.size;
}

const LANG_RE = /\b(does ?n[o']?t speak english|do not speak english|cant speak english|cannot speak english|doesnt understand english|no english|broken english|language barrier|no language|need (a )?translator|only speaks?|speaks? (only )?(mandarin|chinese|cantonese|malay|tamil|hindi|arabic|vietnamese|spanish|french|korean|japanese|thai|burmese|bengali|urdu|nepali)|only (mandarin|chinese|malay|tamil|hindi|arabic))\b/;
const UNDER18_RE = /\b(under 18|under age|underage|below 18|not 18|minor|15 ?(yo|years)|16 ?(yo|years)|17 ?(yo|years)|14 ?(years|yo)|13 ?(years|yo)|too young)\b/;
const TECH_WN_RE = /\b(invalid number(?! format)|invalid num(?!ber format)|invalid email|number is incorrect|number incorrect|incorrect number|number is not correct|number not correct|number is wrong|number not in service|not in services?|number does not exist|no such number|number (is )?not valid|email (is )?not valid|mail (is )?not valid|not a valid (phone|number|email|num|mail|no)|not valid for \w+|not fixable|not fixible)\b/;
const HUMAN_WN_RE = /\b(wrong number|wrong no\b|wrong num\b|wrong name|not the (right )?(person|number|one)|not the registered|didnt register|did not register|didnt regster|did not regster|not registered|im not (the|him|her|that)|no its not|its not me|said not me|directly said not me|claimed wrong|registered.{0,15}(not him|not her|not me|wrong))\b/;
const WRONGNUM_RE = /\b(invalid number(?! format)|invalid num(?!ber format)|invalid email|number is incorrect|number incorrect|incorrect number|number is not correct|number not correct|number is wrong|number not in service|not in services?|number does not exist|no such number|wrong number|wrong no\b|wrong num\b|wrong name|didnt register|not registered|no its not|claimed wrong|number (is )?not valid|email (is )?not valid|mail (is )?not valid|not a valid (phone|number|email|num|mail|no)|not valid for \w+|not fixable|not fixible)\b/;
// Identity CONFIRMED = it is the right person on the line. When the correct account holder is
// reached, a "did not register / someone pranked me" claim is the real owner's denial/forgetfulness
// (=> Recall, keep base) and must NOT be escalated to Denied Registration / Wrong Number.
const CONFIRMED_ID_RE = /\b(confirmed (his|her|the) ?name|confirmed name|name (is )?confirmed|name confirmed|confirmed (his|her) identity|verified (his|her) name|correct person|right person|it is him|its him|it is her|its her|someone prank|got prank(ed)?|was prank(ed)?|pranked)\b/;
const CANCEL_RE = /\b(cancel it|wanna cancel|want to cancel|wants to cancel|please cancel|cancel pls|cancel my|cancel the registration|iptal)\b/;
const THIRDPARTY_RE = /\b(her daughter|his daughter|my daughter|her son|his son|my son|someone else (did|registered|made)|did not do anything|didnt do anything|registration (was )?(made|done) by|reg(istered)? by (her|his|my))\b/;
const PROFILE_RE = /\b(age|exp|job)\b\s*[:\-]/;
const PICKSAID_RE = /\b(pu|picked up|pick up|answered)\b/;

// Words that are NOT a real customer statement (only used to detect "no real conversation").
const TRIVIAL = new Set(("intro mumbling mumble screaming scream watching football game goal match silent silently " +
"name face halo hai hii hey picked picking wasnt wasn werent wernt aswering heating heard hearing proper " +
"properly response respond responding understand understood understanding completed complete immediately " +
"quickly just only after on while then said says saying nothing anything woman man lady guy background " +
"language his her him hers hung hang hangs disconnect cut couldnt could didnt doesnt yes ok okay hmm " +
"with all i was is am are be been being he she they we you your my our their this that these those it its " +
"to of in at by for from as so but and or if when where what why how who whom a an the not no yes pu hu " +
"db na vm dvm cnbr ndt rej reject rejected ringing busy switched off unreachable beep beeps beeping " +
"short long ring rings rang up down out back again very too more most some any one two three four five " +
"call called calling number line speak speaking spoke talk talked talking person again on off " +
"someone else with sorry completed valid invalid checked check support webpage vendor vendors diffrent " +
"different slot slots mail fixable fixed reachable register registered registration activation pending " +
"format link sent network coverage area asked ask can cant cannot speak english spoke had to have got " +
"get getting reply replied replying available unavailable now today still trying tried try contact " +
"contacted attempt attempted dialed dialled reach reached respond responded answering answered answer " +
"cut cuts cutting dropped drop hold holding put busy noisy noise listen listening voice clear unclear " +
"breaking distorted poor weak signal connection connect connecting connected couldnt couldn wouldnt " +
"wont will would shall may might must do does done cb rejecting calls havent hasnt haven hasn " +
"dialers dialer having issue issues slot slots slost put check number you have the " +
"people same times every according webpage fixable").split(/\s+/).filter(Boolean));

function foldBasic(s) {
  return String(s || "").toLowerCase()
    .replace(/\u0131/g, "i").replace(/\u0307/g, "")
    .replace(/ş/g, "s").replace(/ğ/g, "g").replace(/ç/g, "c")
    .replace(/ö/g, "o").replace(/ü/g, "u");
}

function foldedTokens(t) {
  return foldBasic(t)
    .replace(/[^a-z0-9 ]/g, " ")
    .replace(/\b[a-z]\d+\b/g, " ")
    .replace(/\b\d+\b/g, " ")
    .split(/\s+/)
    .filter(x => x.length > 1);
}

function isTrivialLine(text) {
  const toks = foldedTokens(text);
  if (!toks.length) return true;
  return toks.every(tok => TRIVIAL.has(tok) || NO_ANSWER_WORDS.has(tok));
}

// Number of REAL content words in a line (not no-answer/dialer tokens, not trivial filler).
// Dialer noise like "directly voice mail", "puhu no respond", "na dvm interwined" has
// at most 1 stray junk token, while a genuine customer comment has several content words.
function contentWordCount(text) {
  const toks = foldedTokens(text);
  let c = 0;
  for (const t of toks) { if (!NO_ANSWER_WORDS.has(t) && !TRIVIAL.has(t)) c++; }
  return c;
}

// Post-process the base (rule-matched) status with the manually-validated policy tree.
const CONFIDENT_B = new Set(["No Language", "Invalid Country", "Denied Registration", "Wrong Number or Email", "Potential", "Under 18"]);

// Returns the first concrete substring that a policy regex matched, so the report
// can show WHICH word drove the decision (helps trace wrong classifications).
function firstMatch(re, list) {
  for (const p of list) { const m = p.normalized.match(re); if (m) return m[0]; }
  return "";
}

// applyPolicy now returns { status, source, word } so the report can explain the
// decision: source = "sheet_rule" (kept the sheet status) or "policy:<branch>".
function applyPolicy(b, parts, rulesList, crmStatus) {
  const D = (status, source, word) => ({ status: status, source: source, word: word || "" });
  const crmCanon = statusCanon(crmStatus);
  const crmIsCallAgainFamily = (crmCanon === "call again" || crmCanon === "recall");
  const baseIsCallAgainFamily = (b === "Call Again" || b === "Recall" || crmIsCallAgainFamily);
  if (b === "Manual Check") return D(b, "base", "");
  const nonSys = parts.filter(p => !isSystemComment(p.text));
  const convo = nonSys.filter(p => !isNoAnswerOnlyLine(p.text));
  const meaningful = convo.filter(p => !isTrivialLine(p.text) && !WRONGNUM_RE.test(p.normalized));
  const newest = meaningful.length ? meaningful[0].normalized : "";
  const anyM = (re) => meaningful.some(p => re.test(p.normalized));
  const daysM = (re) => {
    const d = new Set();
    meaningful.forEach((p, i) => { if (re.test(p.normalized)) d.add(p.date || ("i" + i)); });
    return d;
  };

  const naDaySet = new Set();
  for (const p of parts) if (isNoAnswerOnlyLine(p.text) && p.date) naDaySet.add(p.date);
  const naDays = naDaySet.size;

  // RECENT no-answer STREAK: distinct no-answer DAYS in the LATEST uninterrupted run, i.e.
  // newer than the most recent real contact (a non-system, non-no-answer line). A genuine
  // pickup/conversation RESETS the streak -> "No Answer 5 UP" needs 5+ DIFFERENT days in the
  // most recent no-answer run (not 5 days scattered across pickups). [policy: "son 5 arama
  // farkli gunlerde olmali"].
  const tsOf = (p) => {
    const m = String(p.raw || "").match(/(\d{4})-(\d{2})-(\d{2})\s+(\d{1,2}):(\d{2})/);
    if (m) return Date.UTC(+m[1], +m[2] - 1, +m[3], +m[4], +m[5]);
    return p.date ? Date.parse(p.date) : 0;
  };
  const nsOrder = nonSys.slice();
  if (nsOrder.length && nsOrder.every(p => tsOf(p))) nsOrder.sort((a, b) => tsOf(b) - tsOf(a));
  let streakContactIdx = -1;
  for (let i = 0; i < nsOrder.length; i++) { if (!isNoAnswerOnlyLine(nsOrder[i].text)) { streakContactIdx = i; break; } }
  const streakSet = new Set();
  const streakEnd = streakContactIdx === -1 ? nsOrder.length : streakContactIdx;
  for (let i = 0; i < streakEnd; i++) { if (isNoAnswerOnlyLine(nsOrder[i].text) && nsOrder[i].date) streakSet.add(nsOrder[i].date); }
  const naStreakDays = streakSet.size;

  const techLines = nonSys.filter(p => TECH_WN_RE.test(p.normalized));
  const humanLines = nonSys.filter(p => HUMAN_WN_RE.test(p.normalized));
  const techConfirmed = techLines.length >= 2 || techLines.some(p => /support|confirm|crm/.test(p.normalized));
  const humanDaySet = new Set();
  humanLines.forEach((p, i) => humanDaySet.add(p.date || ("h" + i)));
  const humanDays = humanDaySet.size;

  const curseAny = anyM(CURSE_RE);
  const fakeRegNewest = (function(){ for (const p of nonSys){ if(!isNoAnswerOnlyLine(p.text)) return FAKEREG_RE.test(p.normalized); } return false; })();
  const strongDays = daysM(STRONG_RE);
  const softDays = daysM(SOFT_RE);
  const negDays = new Set([...strongDays, ...softDays]).size;
  const deferAny = (newest && DEFER_RE.test(newest)) || anyM(DEFER_RE);
  const investedNewest = !!(newest && INVESTED_RE.test(newest));
  const arrangeNewest = !!(newest && (ARRANGE_RE.test(newest) || FP_RE.test(newest) || EMAILC_RE.test(newest) || TIME_RE.test(newest)));
  const negNewest = !!(newest && STRONG_RE.test(newest));
  const arrangeAny = anyM(ARRANGE_RE) || anyM(FP_RE) || anyM(EMAILC_RE) || anyM(TIME_RE);
  const moneyNewest = !!(newest && (MONEY_RE.test(newest) || HEALTH_RE.test(newest)));
  const moneyAny = anyM(MONEY_RE) || anyM(HEALTH_RE);
  const under18 = anyM(UNDER18_RE);
  const thirdparty = anyM(THIRDPARTY_RE);
  const cancelAny = anyM(CANCEL_RE);
  const idConfirmed = anyM(CONFIRMED_ID_RE);
  // A wrong-number/denial signal counts for escalation only when the line is NOT a confirmed-identity
  // line (real owner saying "I didn't register / got pranked" stays Recall via base).
  const wnGenuine = nonSys.some(p => (TECH_WN_RE.test(p.normalized) || HUMAN_WN_RE.test(p.normalized)) && !CONFIRMED_ID_RE.test(p.normalized));
  const profileAny = nonSys.some(p => PROFILE_RE.test(p.normalized));
  const pickSaid = !!(newest && PICKSAID_RE.test(newest) && /\b(said|asked|told|talk|talked|spoke|something|directly)\b/.test(newest));
  // "Real comment" = a customer line with at least 2 genuine content words that is not a
  // no-answer/dialer log and not a wrong-number line. This keeps dialer noise (e.g.
  // "directly voice mail", "puhu no respond", "na dvm interwined") OUT, while letting real
  // conversations ("she saw it was from uob and hung up", "said not good with tech") count.
  const hasReal = nonSys.some(p =>
    !isNoAnswerOnlyLine(p.text) &&
    !WRONGNUM_RE.test(p.normalized) &&
    contentWordCount(p.text) >= 2
  );

  // ---- precedence (most decisive signals first) ----
  if (curseAny && !fakeRegNewest) return D("No Interest", "policy:curse", firstMatch(CURSE_RE, meaningful));
  if ((techConfirmed || humanDays >= 2) && wnGenuine) return D("Wrong Number or Email", "policy:wrong_number", firstMatch(TECH_WN_RE, nonSys) || firstMatch(HUMAN_WN_RE, nonSys));
  if (humanDays === 1 && wnGenuine) return D("Denied Registration", "policy:denied_registration(1x)", firstMatch(HUMAN_WN_RE, nonSys));
  // No Language is a PROTECTED (hard) base: a clear language barrier must not be overridden by
  // an (often uncertain) refusal/cancel or a stale callback. Keep No Language.
  if (b === "No Language") return D("No Language", "base:no_language(protected)", firstMatch(LANG_RE, nonSys) || "no language");
  // No Interest from sheet repeat (2+ refusal days) must not be downgraded back to Recall.
  if (b === "No Interest") return D("No Interest", "base:no_interest(protected)", firstMatch(STRONG_RE, meaningful) || firstMatch(SOFT_RE, meaningful));
  if (fakeRegNewest && !(anyM(LANG_RE) || b === "No Language")) return D("Wrong Number or Email", "policy:fake_registration", firstMatch(FAKEREG_RE, nonSys) || "fake name");
  // 2+ different days with a real refusal/recall utterance => No Interest (na/vm alone does NOT count).
  // BUT if the NEWEST comment also closes with callback/appointment, closing intent wins -> Call Again (handled below).
  if (countRefusalDays(parts, rulesList) >= 2 && !arrangeNewest) return D("No Interest", "policy:refusal_2_days", firstMatch(STRONG_RE, meaningful) || firstMatch(SOFT_RE, meaningful));
  // Recall then 3+ distinct na/vm-only days (no real talk between) => gave up => No Interest.
  if (countNaDaysAfterFirstRefusal(parts, rulesList) >= 3) return D("No Interest", "policy:recall_3na_after", "3 na days after recall");
  if (thirdparty) return D("Recall", "policy:third_party", firstMatch(THIRDPARTY_RE, meaningful));
  if (deferAny) return D("Recall", "policy:defer", firstMatch(DEFER_RE, meaningful));
  if (investedNewest && !arrangeNewest) return D("Recall", "policy:already_invested", firstMatch(INVESTED_RE, meaningful));
  if (cancelAny && !(newest && CANCEL_RE.test(newest)) && naDays >= 3) return D("No Interest", "policy:cancel+no_answer", firstMatch(CANCEL_RE, meaningful));
  // "no income"/"no money" alone must NOT decide when the SAME (newest) comment also shows
  // refusal / cancel / distrust ("too good to be true", "wanted to cancel", "wanna end the call").
  // In that case the disposition is the refusal -> handled below (Recall first, No Interest on repeat).
  if (!negNewest && ((moneyNewest && !arrangeNewest) || (moneyAny && !arrangeAny))) {
    // Keep more specific sheet status (e.g. "No Potential - no documents") instead of collapsing.
    if (/^no potential/i.test(String(b || ""))) {
      return D(b, "policy:no_money(keep_sheet)", firstMatch(MONEY_RE, meaningful) || firstMatch(HEALTH_RE, meaningful) || "no money");
    }
    return D("No Potential", "policy:no_money", firstMatch(MONEY_RE, meaningful) || firstMatch(HEALTH_RE, meaningful));
  }
  // Recency: a clear refusal/cancel in the NEWEST meaningful comment outranks an
  // OLDER call-back/arrange signal ("first said call later, THEN refused" -> Recall, not Call Again).
  if (negNewest && !arrangeNewest) return D("Recall", "policy:refusal_in_newest", firstMatch(STRONG_RE, meaningful));
  if (negDays >= 1 && !arrangeNewest) return D("Recall", "policy:refusal", firstMatch(STRONG_RE, meaningful) || firstMatch(SOFT_RE, meaningful));
  // CONVERSATION-BASED outcomes win over a blanket no-answer promotion.
  // If a real comment is visible, classify by the COMMENT - the trailing no-answer
  // lines must not turn a "Call Again"/"Under 18" etc. into a No Answer status.
  // Newer NA/rej alone does NOT kill Call Again until 5 DISTINCT no-answer days.
  // Only a hard refusal in newest meaningful comment beats an older callback.
  const newestNonSys = nonSys[0];
  const newestIsNaOnly = !!(newestNonSys && isNoAnswerOnlyLine(newestNonSys.text));
  // If newest lines are only na/rej but streak < 5, still honor an older agreed callback → Call Again.
  if (newestIsNaOnly && naStreakDays < 5 && (arrangeAny || arrangeNewest) && !moneyAny && !negNewest && negDays < 1) {
    return D("Call Again", "policy:callback_kept_until_5na", firstMatch(ARRANGE_RE, meaningful) || firstMatch(FP_RE, meaningful) || "callback kept (<5 na days)");
  }
  if (arrangeNewest && !newestIsNaOnly) return D("Call Again", "policy:callback_in_newest", firstMatch(ARRANGE_RE, meaningful) || firstMatch(FP_RE, meaningful) || firstMatch(EMAILC_RE, meaningful) || firstMatch(TIME_RE, meaningful));
  if (under18 && !moneyAny) return D("Under 18", "policy:under_18", firstMatch(UNDER18_RE, meaningful));
  // Stale callback vs refusal: old "call me later" must NOT beat a newer refusal. NA-only does not count here.
  if (arrangeAny && !moneyAny && !negNewest && negDays < 1 && !newestIsNaOnly) return D("Call Again", "policy:callback", firstMatch(ARRANGE_RE, meaningful) || firstMatch(FP_RE, meaningful) || firstMatch(EMAILC_RE, meaningful) || firstMatch(TIME_RE, meaningful));
  if (negDays >= 1) return D("Recall", "policy:refusal", firstMatch(STRONG_RE, meaningful) || firstMatch(SOFT_RE, meaningful));
  if (under18) return D("Under 18", "policy:under_18", firstMatch(UNDER18_RE, meaningful));
  if (pickSaid && profileAny && naDays <= 1) return D("Call Again", "policy:picked_up+profile", "pu + profile note");

  // ---- No conversation signal fired. Only no-answer / unresolved bases remain. ----
  // A real status from a sheet rule (Wrong Number, Recall, No Potential, Denied Registration,
  // etc.) must NEVER be overwritten by a no-answer fallback - keep the comment-derived status.
  const baseIsUnresolved = (b === "No Answer 1-5" || b === "No Answer 5 UP" || b === "AI" || b === "" || b == null);
  const baseAllowsNaPromote = baseIsUnresolved || b === "Call Again" || b === "Recall";
  if (!baseAllowsNaPromote) return D(b, "sheet_rule", "");
  // Base is no-answer / unresolved (or Call Again/Recall with only na streak) -> no-answer days decide.
  // POLICY: "if a real comment is visible, act on the comment". A genuine customer
  // conversation must drive the decision even when 5+ no-answer days followed it, so it
  // goes to the AI rather than being forced into No Answer 5 UP. (hasReal already excludes
  // dialer/voicemail noise via contentWordCount.)
  // Pickup + busy/lm/callback intent is a real contact even when contentWordCount is low.
  // Keep Call Again if newest is only short na/rej but streak is still under 5 distinct days.
  const busyPickup = nonSys.find(p => isBusyAfterPickup(p.text));
  if (busyPickup && (!newestIsNaOnly || naStreakDays < 5)) {
    if (newestIsNaOnly && naStreakDays >= 5) {
      /* fall through to 5 UP */ 
    } else {
      return D("Call Again", "policy:busy_after_pickup", (busyPickup.text || "").slice(0, 60));
    }
  }
  // Call Again / Recall (engine OR CRM) → No Answer ONLY after 5+ DISTINCT no-answer days.
  // Fewer than 5 days of na/rej must NOT erase Call Again.
  if (baseIsCallAgainFamily && naStreakDays >= 5 && (newestIsNaOnly || !hasReal)) {
    return D("No Answer 5 UP", "policy:call_again_5na_days", "streak days=" + naStreakDays + " (total=" + naDays + ")");
  }
  // ONLY protect when CRM is already Call Again / Recall.
  // Do NOT re-label a sheet promotion (NA -> Call Again via "currently busy") as keep-under-5na.
  if (crmIsCallAgainFamily && naStreakDays < 5) {
    const keep = crmCanon === "recall" ? "Recall" : "Call Again";
    // Sheet/policy already chose Call Again/Recall, or base is unresolved/NA — keep CRM family.
    if (b === "Call Again" || b === "Recall" || b === "AI" || b === "No Answer 1-5" || b === "No Answer 5 UP" || !b || newestIsNaOnly) {
      return D(keep, "policy:call_again_kept_under_5na", "streak days=" + naStreakDays + " (<5, keep " + keep + ")");
    }
  }
  if (hasReal) return D("AI", "to_ai:comment_present", "no-answer days=" + naDays);
  // No real conversation -> the LATEST no-answer run must span 5+ DISTINCT days. A pickup in
  // between resets the run, so "answered once then a few more no-answers" is NOT 5 UP.
  if (naStreakDays >= 5) return D("No Answer 5 UP", "policy:no_answer_5_distinct_days", "streak days=" + naStreakDays + " (total=" + naDays + ")");
  if (baseIsUnresolved) return D("No Answer 1-5", "policy:no_real_conversation", "streak days=" + naStreakDays + " (total=" + naDays + ")");
  return D(b, "sheet_rule", "");
}

const leads = [];
const rules = [];

for (const item of inputItems) {
  const j = item.json;

  if (j["account no"]) leads.push(j);

  if (
    j.trigger_phrase &&
    String(j.active).toLowerCase() !== "false"
  ) {
    // Sheet governance: AI-proposed rules must be human-approved before they fire.
    const src = String(j.source || j.origin || j.created_by || j.rule_source || "").toLowerCase();
    const kg = String(j.keyword_group || "").toLowerCase().trim();
    const aiLike = src.includes("ai") || kg === "ai_generated" || String(j.ai_generated || "").toLowerCase() === "true";
    const approved = ["true", "yes", "1"].includes(String(j.human_approved || j.reviewed || j.approved || "").toLowerCase());
    if (aiLike && !approved) {
      continue; // skip aggressive unreviewed AI sheet rows
    }
    // Soft governance: very short AI-like triggers are unsafe even if marked active
    const trig = String(j.trigger_phrase || "").trim();
    if (aiLike && trig.length < 5) continue;
    rules.push(j);
  }
}

const results = [];

for (const lead of leads) {
  const rawComments = lead["last 10 comments"] || "";
  const parts = sortPartsNewestFirst(extractCommentParts(rawComments));
  const fullComment = normalize(rawComments);

  // Decline / Duplicate / DNC cannot be auto-classified from comments -> Manual Check only, never AI.
  const MANUAL_CRM = { decline: "Decline", duplicate: "Duplicate", dnc: "DNC", potential: "Potential", "in progress": "In progress", new: "New" };
  const crmLow = String(lead["customer status"] || "").trim().toLowerCase().replace(/\s+/g, " ");
  if (MANUAL_CRM[crmLow]) {
    const label = String(lead["customer status"] || "").trim() || MANUAL_CRM[crmLow];
    results.push({
      json: {
        ...lead,
        memory_matched: true,
        skipAI: true,
        "Validation Result": "Manual Check",
        "Suggested Status": label,
        "Reason": "Customer status is " + label + " - flagged for MANUAL CHECK (not auto-classified).",
        "Decision Source": label + " (manual check)",
        "Matched Sheet Row": "-",
        "Matched Keyword": "customer status = " + label,
        "Appointment Detected": "No",
        "Appointment Status": "No Appointment",
        "Appointment Outcome": "No Appointment",
        "Appointment Detail": ""
      }
    });
    continue;
  }

  const meaningfulConversationExists =
    hasMeaningfulCustomerConversation(parts);

  // Conversation lines only (exclude email subjects / "In progress" / system logs)
  // so a rule can NEVER match inside an email subject line. Newest comment is index 0.
  const convoParts = parts.filter(p => !isSystemComment(p.text));

  const matches = [];
  const naStreakDaysLead = countNaStreakDays(parts);
  const callAgainProtected = crmCallAgainProtected(lead["customer status"], naStreakDaysLead);

  for (const rule of rules) {
    const trigger = normalize(rule.trigger_phrase);
    const keywordGroup = String(rule.keyword_group || "").toLowerCase().trim();

    if (!trigger) continue;

    if (keywordGroup === "no_answer") {
      // SHEET GUARD: short no_answer triggers (na/rej/busy/navm) must NOT demote CRM Call Again until 5 distinct NA days.
      if (callAgainProtected) continue;
      let idx = -1;
      for (let k = 0; k < parts.length; k++) {
        const pt = parts[k].text;
        // "busy" in "pu ... lm busy" is a real contact, not a no-answer-only line — skip sheet row 397 false match.
        if (trigger === "busy" && isBusyAfterPickup(pt)) continue;
        if (isNoAnswerOnlyLine(pt) && normalize(pt).includes(trigger)) {
          idx = k;
          break;
        }
      }
      if (idx !== -1) {
        matches.push({ rule, trigger, priority: 1, recency: idx });
      }
      continue;
    }

    // Non-no-answer rules match ONLY inside real conversation lines (no email/system lines).
    // Approved sheet guards:
    //  - "currently busy" must NOT promote to Call Again (telecom busy = No Answer)
    //  - "invalid mail/email" must NOT force Denied Registration / Wrong Number
    const sugLow = String(rule.suggested_status || "").toLowerCase();
    if ((trigger === "currently busy" || trigger === "busy") && /call again/.test(sugLow)) continue;
    if (/invalid mail|invalid email/.test(trigger) && /(denied|wrong number)/.test(sugLow)) continue;
    let idx = -1;
    for (let k = 0; k < convoParts.length; k++) {
      if (isAgentStatusNote(convoParts[k].text, trigger)) continue;
      if (convoParts[k].normalized.includes(trigger)) {
        idx = k;
        break;
      }
    }
    if (idx !== -1) {
      // Priority tiers: negative outcomes / money / language / contact (100) outrank
      // positive/appointment (80), which outrank soft follow-ups (50). This way a refusal
      // like "i dont want it" beats "on the deposit page", and "no payment method" beats
      // "call me after", while a stray "call again" never overrides a real outcome.
      let priority;
      if (keywordGroup === "follow_up") priority = 50;
      else if (keywordGroup === "positive" || keywordGroup === "appointment") priority = 80;
      else if (keywordGroup === "denied") priority = 110;
      else priority = 100;
      matches.push({ rule, trigger, priority, recency: idx });
    }
  }

  // ---- BASE STATUS: rule matching + repeat logic (prior engine) ----
  let baseStatus;
  let baseTrigger = "";
  let baseRow = "";
  let baseKeyword = "";
  if (matches.length === 0) {
    baseStatus = "AI";
  } else {
    // Prefer real-intent (non-no-answer) matches. Among them, the rule matching the
    // NEWEST conversation line wins, then higher priority, then the longest trigger.
    const nonNoAnswer = matches.filter(m =>
      String(m.rule.keyword_group || "").toLowerCase().trim() !== "no_answer"
    );
    const pool = nonNoAnswer.length ? nonNoAnswer : matches;
    pool.sort((a, b) => {
      if (b.priority !== a.priority) return b.priority - a.priority;
      if (a.recency !== b.recency) return a.recency - b.recency;
      return b.trigger.length - a.trigger.length;
    });
    const selected = pool[0];
    const matchedRule = selected.rule;
    baseTrigger = matchedRule.trigger_phrase || "";
    baseRow = (matchedRule.row_number != null ? matchedRule.row_number : "");
    baseKeyword = String(matchedRule.keyword_group || "").toLowerCase().trim();
    const trigger = selected.trigger;
    const keywordGroup = String(matchedRule.keyword_group || "").toLowerCase().trim();
    const repeatLogic = String(matchedRule.repeat_logic || "direct_final").trim();
    const firstStatus = String(matchedRule.first_status || matchedRule.suggested_status || "").trim();
    const repeatStatus = String(matchedRule.repeat_status || matchedRule.suggested_status || "").trim();
    let suggestedStatus = String(matchedRule.suggested_status || firstStatus || repeatStatus).trim();

    if (repeatLogic === "refusal_day_repeat" || (repeatLogic === "different_day_repeat" && keywordGroup === "rejection")) {
      suggestedStatus = countRefusalDays(parts, rules) >= 2 ? repeatStatus : firstStatus;
    } else if (repeatLogic === "different_day_repeat") {
      suggestedStatus = countTriggerDays(parts, trigger) >= 2 ? repeatStatus : firstStatus;
    } else if (repeatLogic === "no_answer_count") {
      suggestedStatus = countNoAnswerDays(parts) > 5 ? repeatStatus : firstStatus;
    }

    if (keywordGroup === "no_answer" && meaningfulConversationExists) {
      // Only a no-answer rule matched but a REAL comment is also present. Never label this
      // "No Answer 1-5" - the comment must drive the decision. Promote to 5 UP only when the
      // no-answer falls on 5+ DISTINCT days; otherwise hand to the policy/AI layer to read
      // the comment.
      const naDayCount = new Set(parts.filter(p => isNoAnswerOnlyLine(p.text) && p.date).map(p => p.date)).size;
      baseStatus = naDayCount >= 5 ? "No Answer 5 UP" : "AI";
    } else {
      const softStatuses = new Set(["No Interest", "No Potential", "Recall", "Call Again"]);
      if (meaningfulConversationExists && softStatuses.has(suggestedStatus)) {
        let newestConvo = "";
        for (const p of parts) {
          if (!isSystemComment(p.text) && !isNoAnswerOnlyLine(p.text)) { newestConvo = p.text; break; }
        }
        const newestNorm = normalize(newestConvo);
        const newestRefusal = STRONG_RE.test(newestNorm) || SOFT_RE.test(newestNorm);
        if (!newestRefusal && hasFuturePromise(newestConvo)) {
          suggestedStatus = hasMoneyIssue(fullComment) ? "Recall" : "Call Again";
        }
      }
      baseStatus = suggestedStatus;
      // Business rule: currently busy / telecom busy without pickup talk => No Answer, never Call Again.
      if (/currently busy/.test(String(baseTrigger || "").toLowerCase()) ||
          (/^busy$/.test(String(baseTrigger || "").toLowerCase()) && /call again/i.test(String(suggestedStatus || "")))) {
        baseStatus = "No Answer 1-5";
      }
    }
  }

  // ---- POLICY LAYER (manually validated) ----
  const pol = applyPolicy(baseStatus, parts, rules, lead["customer status"]);
  const finalStatus = pol.status;

  if (finalStatus === "AI") {
    results.push({ json: { ...lead, memory_matched: false, skipAI: false } });
  } else {
    const cur = String(lead["customer status"] || "").trim();

    // ---- Build a human-readable decision trace (why this status?) ----
    let decisionSource, matchedRowOut, matchedWordOut, reasonText;
    const baseFromSheet = (baseStatus !== "AI" && baseRow !== "");
    if (pol.source === "sheet_rule") {
      // The sheet rule status was kept as-is (no policy override).
      decisionSource = baseFromSheet ? ("Sheet rule (row " + baseRow + ")") : "Sheet rule";
      matchedRowOut = baseRow !== "" ? baseRow : "-";
      matchedWordOut = baseTrigger || "";
      reasonText = "Sheet row " + matchedRowOut + " trigger '" + (baseTrigger || "") +
                   "' [" + (baseKeyword || "") + "] => " + finalStatus;
    } else {
      // A policy detector decided the final status (may override a sheet base).
      decisionSource = "Policy: " + pol.source.replace(/^policy:/, "");
      matchedRowOut = baseFromSheet ? baseRow : "-";
      matchedWordOut = pol.word || baseTrigger || "";
      const basePart = baseFromSheet
        ? ("Sheet row " + baseRow + " '" + baseTrigger + "' => " + baseStatus + " | ")
        : (baseStatus !== "AI" ? ("base " + baseStatus + " | ") : "");
      reasonText = basePart + pol.source.replace(/^policy:/, "policy ") +
                   (pol.word ? (" [matched: '" + pol.word + "']") : "") + " => " + finalStatus;
    }

    results.push({
      json: {
        ...lead,
        memory_matched: true,
        skipAI: true,
        matched_trigger: baseTrigger,
        "Validation Result": statusEquals(cur, finalStatus) ? "Correct" : "Wrong",
        "Suggested Status": statusEquals(cur, finalStatus) ? preferSpecificStatus(finalStatus, cur) : finalStatus,
        "Reason": reasonText,
        "Decision Source": decisionSource,
        "Matched Sheet Row": matchedRowOut,
        "Matched Keyword": matchedWordOut,
        "Appointment Detected": "No",
        "Appointment Status": "No Appointment",
        "Appointment Outcome": "No Appointment",
        "Appointment Detail": ""
      }
    });
  }
}

return results;

const today = new Date().toISOString().split('T')[0];
// Standard transition rules: Denied Registration -> Wrong Number on a later-day repeat
const phrases = [
  'wrong person',
  'this is not me',
  'not the person'
];
return phrases.map(phrase => ({
  json: {
    trigger_phrase: phrase,
    intent: 'denied_registration',
    suggested_status: 'Denied Registration',
    confidence: 100,
    priority: 'high',
    when_to_use: 'Client claims they are not the registered person',
    when_not_to_use: 'If client says it is their name but they did not register -> No Interest',
    active: true,
    keyword_group: 'identity',
    example_comment: phrase,
    correction_source: 'standard_rule',
    created_date: today,
    repeat_logic: 'different_day_repeat',
    first_status: 'Denied Registration',
    repeat_status: 'Wrong Number'
  }
}));

// Verify leads that need a second opinion:
//   - Validation Result = Wrong (CRM status differs from suggested — excel "Wrong" rows)
//   - AI Agent decisions, mixed refusal+callback, rule/status conflict
//   - Excel/Sheet-driven matches (Sheet rule, Matched Keyword, Matched Sheet Row)
// No-answer statuses are mechanical and always skipped.
const allRows = $input.all().map(i => i.json);
const isNA = s => /no\s*answer/i.test(String(s || ""));
function needsVerifier(j) {
  const vr = String(j["Validation Result"] || "").toLowerCase();
  const src = String(j["Decision Source"] || "");
  const sug = String(j["Suggested Status"] || "");
  if (isNA(sug) || isNA(j["customer status"])) return false; // mechanical
  if (vr === "wrong") return true;
  if (/AI Agent/i.test(src)) return true;
  if (/Sheet rule/i.test(src) && vr !== "correct") return true;
  if (/Manual Check/i.test(vr)) return true;
  // Correct + deterministic/policy/memory => skip verifier (0 token save)
  return false;
}
const rows = allRows.filter(needsVerifier);

let ruleItems = [];
try { ruleItems = $("Get row(s) in sheet").all().map(i => i.json); } catch (e) { ruleItems = []; }

const norm = s => String(s || "")
  .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
  .replace(/\u0131/g, "i").replace(/I/g, "i")
  .toLowerCase().replace(/[^a-z0-9 ]+/g, " ").replace(/\s+/g, " ").trim();

function canonStatus(s) {
  const n = norm(s);
  if (!n) return "";
  if (/(no answer.*5|5 up)/.test(n)) return "no answer 5 up";
  if (/no answer/.test(n)) return "no answer 1-5";
  if (/(wrong number|wrong email)/.test(n)) return "wrong number or email";
  if (/denied reg/.test(n)) return "denied registration";
  if (/no interest/.test(n)) return "no interest";
  if (/no potential/.test(n)) return "no potential";
  if (/(no language|language)/.test(n)) return "no language";
  if (/invalid country/.test(n)) return "invalid country";
  if (/under\s*18/.test(n)) return "under 18";
  if (/call again/.test(n)) return "call again";
  if (/recall/.test(n)) return "recall";
  if (/duplicate/.test(n)) return "duplicate";
  if (/decline/.test(n)) return "decline";
  return n;
}

const rules = ruleItems
  .filter(r => r && r.trigger_phrase && String(r.active).toLowerCase() !== "false")
  .map(r => ({
    phrase: String(r.trigger_phrase),
    nrm: norm(r.trigger_phrase),
    status: String(r.suggested_status || ""),
    use: String(r.when_to_use || "").slice(0, 70),
    avoid: String(r.when_not_to_use || "").slice(0, 70),
    first: String(r.first_status || ""),
    repeat: String(r.repeat_status || ""),
    prio: String(r.priority || "").toLowerCase()
  }))
  .filter(r => r.nrm.length >= 3);

function segments(raw) {
  return String(raw || "").split("||").map(seg => {
    const parts = seg.split("|");
    const body = parts.length >= 3 ? parts.slice(2).join(" ").trim() : seg.trim();
    const date = parts.length >= 3 ? parts[0].trim() : "";
    return { date, body, nbody: norm(body) };
  }).filter(s => s.body);
}

const REFUSAL = /\b(not interested|no interest|dont want|do not want|stop calling|leave me alone|scammer|no money|broke|cant afford|no funds|not registering|wont register)\b/;
const CALLBACK = /\b(call me|call back|callback|cb|cbk|clbk|ring me|reach me|call tomorrow|call later|call again|tomorrow|ok call|fine call|will call)\b/;

function snippet(body, idx, len) {
  const start = Math.max(0, idx - 30), end = Math.min(body.length, idx + len + 30);
  let s = body.slice(start, end).trim();
  if (start > 0) s = "..." + s;
  if (end < body.length) s = s + "...";
  return s;
}

function matchRulesDetailed(comments) {
  const segs = segments(comments);
  const hits = [];
  for (const r of rules) {
    for (let si = 0; si < segs.length; si++) {
      const idx = segs[si].nbody.indexOf(r.nrm);
      if (idx < 0) continue;
      hits.push({
        phrase: r.phrase, status: r.status, when_to_use: r.use, when_not_to_use: r.avoid,
        first_status: r.first, repeat_status: r.repeat,
        matched_in: si === 0 ? "newest_comment" : "older_comment_" + si,
        context_snippet: snippet(segs[si].body, idx, r.phrase.length),
        prio: r.prio, nlen: r.nrm.length
      });
      break;
    }
  }
  hits.sort((a, b) =>
    ((b.prio === "high") - (a.prio === "high")) ||
    ((a.matched_in === "newest_comment" ? 0 : 1) - (b.matched_in === "newest_comment" ? 0 : 1)) ||
    (b.nlen - a.nlen));
  const seen = new Set(); const out = [];
  for (const h of hits) {
    const k = norm(h.phrase);
    if (seen.has(k)) continue;
    seen.add(k);
    const { prio, nlen, ...rest } = h;
    out.push(rest);
    if (out.length >= 3) break;
  }
  return out;
}

function closingIntent(comments) {
  const segs = segments(comments);
  if (!segs.length) return { closing_intent: "unknown", hint: "no comments" };
  const nb = segs[0].nbody;
  const hasRef = REFUSAL.test(nb), hasCb = CALLBACK.test(nb);
  const lastThird = nb.slice(Math.floor(nb.length * 0.55));
  const closingCb = CALLBACK.test(lastThird);
  const closingRef = REFUSAL.test(lastThird) && !closingCb;
  if (hasRef && hasCb && closingCb) return { closing_intent: "mixed_callback_wins", hint: "Refusal present but NEWEST comment CLOSES with callback -> Call Again likely" };
  if (hasRef && hasCb && closingRef) return { closing_intent: "mixed_refusal_wins", hint: "Mixed but CLOSES with refusal -> Recall/No Interest likely" };
  if (hasRef && hasCb) return { closing_intent: "mixed_review", hint: "Both refusal and callback in newest comment - read full sentence" };
  if (hasCb) return { closing_intent: "callback", hint: "Callback intent in newest comment" };
  if (hasRef) return { closing_intent: "refusal", hint: "Refusal intent in newest comment" };
  return { closing_intent: "other", hint: "No clear refusal/callback in newest comment" };
}

const targets = [];
for (const r of rows) {
  const ss = String(r["Suggested Status"] || "").trim();
  const isValidationWrong = String(r["Validation Result"] || "").trim().toLowerCase() === "wrong";
  if (!ss) continue;
  // Skip mechanical no-answer UNLESS excel marked it Wrong (CRM vs suggested mismatch)
  if (isNA(ss) && !isValidationWrong) continue;

  const comments = String(r["last 10 comments"] || "").slice(0, 350);
  const src = String(r["Decision Source"] || "");
  const matched = matchRulesDetailed(comments);
  const hint = closingIntent(comments);
  const engC = canonStatus(ss);

  const isAI = /ai agent/i.test(src);
  const isMixed = hint.closing_intent.indexOf("mixed") === 0;
  const ruleConflict = matched.some(m => {
    const rc = canonStatus(m.status);
    return rc && rc !== engC && !isNA(m.status);
  });
  // Excel/Sheet match: engine used a sheet rule or matched a keyword from CRM_AI_Rules
  const isSheetDriven = /sheet rule/i.test(src) ||
    String(r["Matched Keyword"] || "").trim().length >= 3 ||
    String(r["Matched Sheet Row"] || "").trim().length > 0 ||
    /sheet row/i.test(String(r["Reason"] || ""));

  if (!(isAI || isMixed || ruleConflict || isSheetDriven || isValidationWrong)) continue;

  targets.push({
    id: String(r["account no"] || ""),
    status: ss,
    comments,
    matched_rules: matched,
    closing_intent: hint.closing_intent,
    context_hint: hint.hint,
    engine_reason: String(r["Reason"] || "").slice(0, 100),
    decision_source: src.slice(0, 60)
  });
}

const BATCH = 40;
const out = [];
for (let i = 0; i < targets.length; i += BATCH) {
  out.push({ json: { batch: targets.slice(i, i + BATCH), batch_index: out.length, count: Math.min(BATCH, targets.length - i) } });
}
if (out.length === 0) out.push({ json: { batch: [], batch_index: 0, count: 0 } });
