// Parse verifier verdicts — ADVISORY ONLY (never changes Suggested Status).
function parseArr(t) {
  try { return JSON.parse(t); }
  catch (e) {
    const m = String(t || "").match(/\[[\s\S]*\]/);
    try { return m ? JSON.parse(m[0]) : []; } catch (e2) { return []; }
  }
}
const norm = s => String(s || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/\u0131/g, "i").replace(/I/g, "i").toLowerCase().replace(/[^a-z0-9 ]+/g, " ").replace(/\s+/g, " ").trim();

function canonStatus(s) {
  const n = norm(s);
  if (!n) return "";
  if (/(no\s*answer.*5|5\s*up)/.test(n)) return "No Answer 5 UP";
  if (/no\s*answer/.test(n)) return "No Answer 1-5";
  if (/(wrong\s*number|wrong\s*email|^wn$)/.test(n)) return "Wrong Number or Email";
  if (/denied\s*reg/.test(n)) return "Denied Registration";
  if (/no\s*interest/.test(n)) return "No Interest";
  if (/no\s*potential/.test(n)) return "No Potential";
  if (/(no\s*language|language)/.test(n)) return "No Language";
  if (/invalid\s*country/.test(n)) return "Invalid Country";
  if (/under\s*18/.test(n)) return "Under 18";
  if (/call\s*again/.test(n)) return "Call Again";
  if (/recall/.test(n)) return "Recall";
  if (/duplicate/.test(n)) return "Duplicate";
  if (/decline/.test(n)) return "Decline";
  return String(s || "").trim();
}

const verdicts = {};
for (const it of $input.all()) {
