// Merge the appointment AI result back onto the report rows.
// - Only updates CANDIDATE rows (those the AI saw).
// - Reconcile status to "Call Again" ONLY for soft statuses (never override hard outcomes).
// - RECENCY GUARD: a STALE callback must NOT override a NEWER refusal / decisive signal.
//   (e.g. "call me after 3 hours" at 02:16, then "not interested" at 06:19 -> keep Recall.)
function parseArr(t){
  try { return JSON.parse(t); }
  catch(e){ const m=String(t||"").match(/\[[\s\S]*\]/); try { return m?JSON.parse(m[0]):[]; } catch(e2){ return []; } }
}
function fold(s){
  return String(s||"").toLowerCase()
    .replace(/\u0131/g,"i").replace(/\u0307/g,"")
    .replace(/ş/g,"s").replace(/ğ/g,"g").replace(/ç/g,"c").replace(/ö/g,"o").replace(/ü/g,"u");
}
// callback / appointment detector (same family as Build Appt Batches)
const APPT_RE = /(call ?back|\bcb\b|\bcbk\b|\bclbk\b|cback|appointment|appt|call me|call him|call her|will call|ask(ed)? to call|ring me|reach me|call on|call at|call by|call next|call after|call again|tomorrow|tmrw|tmr|tmrrw|2moro|today|tonight|next week|nxt week|\b(mon|tue|tues|wed|weds|thu|thur|thurs|fri|sat|sun)(day)?\b|\b\d{1,2}:\d{2}\b|\b\d{1,2}\s?(am|pm)\b|\b\d{4}-\d{2}-\d{2}\b|\b\d{1,2}[\/.]\d{1,2}[\/.]\d{2,4}\b)/;
// decisive signals that make an older/co-located callback stale
const SUPERSEDE_RE = /(not interested|no interest|not intrested|no intrest|refus|declin|do ?n[o']?t call|dont call|stop calling|not keen|no thanks|wrong number|wrong email|invalid email|invalid number|not my number|already registered|under ?18|hung up|abusive|do not disturb|blocked|no potential|no funds?|cannot afford|\brej\b|rejected|navm|\bna\s*vm\b|\bdnd\b|restricted)/;
// Distrust/hostility signals (calling US a scammer, aggression, "report you"). These only make a
// callback stale when they sit in a line STRICTLY NEWER than the callback - NOT in the same line,
// because skepticism resolved within the same comment often ENDS in a genuine callback
// ("i think its a scam ... cleared objections ... call back wednesday" => still Call Again).
const NEWER_SUPERSEDE_RE = /(scammer|scam and|is a scam|you are scam|youre scam|report you|aggressi|agressi)/;

// Split "last 10 comments" into lines (newest-first) with body + timestamp.
function parseLines(raw){
  // Prefer "||" entry delimiter; fall back to newlines. Merge continuation lines (no date).
  const rawStr = String(raw||"");
  const rough = (rawStr.includes("||") ? rawStr.split(/\|\|/) : rawStr.split(/\r?\n/)).map(s => s.trim()).filter(Boolean);
  const segs = [];
  for (const s of rough) {
    if (segs.length && !/\d{4}-\d{2}-\d{2}/.test(s) && !/^email\b/i.test(s) && !/^in progress/i.test(s)) {
      segs[segs.length - 1] = segs[segs.length - 1] + " " + s;
    } else segs.push(s);
  }
  const lines = segs.map((s, idx) => {
    const m = s.match(/(\d{4})-(\d{2})-(\d{2})\s+(\d{1,2}):(\d{2})/);
    const ts = m ? Date.UTC(+m[1], +m[2]-1, +m[3], +m[4], +m[5]) : null;
    const parts = s.split("|");
    const body = parts.length >= 3 ? parts.slice(2).join("|") : s;
    return { idx, ts, body: fold(body).replace(/\s+/g, " ").trim() };
  });
  if (lines.length && lines.every(l => l.ts != null)) lines.sort((a,b) => b.ts - a.ts); // newest-first
  return lines;
}
function looksLikeCommentTimestamp(when) {
  return /^\d{4}-\d{2}-\d{2}([ T]\d{1,2}:\d{2})?$/.test(String(when || "").trim());
}
function statusCanonAppt(s) {
  const x = String(s || "").trim().toLowerCase().replace(/\s+/g, " ");
  if (/no potential/.test(x)) return "no potential";
  if (/call again/.test(x)) return "call again";
  if (/no answer/.test(x) && /5/.test(x)) return "no answer 5 up";
  if (/no answer/.test(x)) return "no answer 1-5";
  return x;
}

// true when a decisive signal sits in the newest callback line OR any line newer than it
function callbackIsStale(raw){
  const lines = parseLines(raw);
  let apptPos = -1;
  for (let i=0;i<lines.length;i++){ if (APPT_RE.test(lines[i].body)){ apptPos=i; break; } }
  if (apptPos === -1) return false;
  for (let i=0;i<=apptPos;i++){ if (SUPERSEDE_RE.test(lines[i].body)) return true; }
  // hostility/distrust only counts when strictly NEWER than the callback line
  for (let i=0;i<apptPos;i++){ if (NEWER_SUPERSEDE_RE.test(lines[i].body)) return true; }
  return false;
}

const appt = {};
for (const it of $input.all()) {
