        j["Appointment Outcome"]  = "No Appointment";
      } else {
        const whenRaw = String(a.when || "").trim();
        const detailRaw = String(a.detail || a.when || "").trim();
        // Reject comment-metadata timestamps presented as appointment times.
        if (looksLikeCommentTimestamp(whenRaw) || looksLikeCommentTimestamp(detailRaw)) {
          j["Appointment Detected"] = "No";
