        j["Appointment Outcome"]  = String(a.outcome || j["Appointment Outcome"] || "");
        // appointment => Call Again, but only when the current status is soft
        if (SOFT.has(String(j["Suggested Status"] || "").trim())) {
          const prevStatus = String(j["Suggested Status"] || "").trim();
          const prevReason = String(j["Reason"] || "");
          const whenTxt = String(j["When To Call"] || j["Appointment Detail"] || "").trim();
          j["Suggested Status"] = "Call Again";
