            statusCanonAppt(j["customer status"]) === "call again" ? "Correct" : "Wrong";
          j["Decision Source"] = "Appointment: callback_detected";
          j["Matched Keyword"] = whenTxt || "callback";
          j["Reason"] = "Appointment/callback detected" +
            (whenTxt ? (" (" + whenTxt + ")") : "") +
            " => Call Again. Previous decision: " + (prevStatus || "-") +
            (prevReason ? (" [" + prevReason + "]") : "");
        }
        }
      }
    } else {
      // AI says it is NOT a real appointment -> fix a regex false-positive (columns only, status untouched)
      j["Appointment Detected"] = "No";
      j["Appointment Status"]   = "No Appointment";
      j["When To Call"]         = "";
      j["Appointment Detail"]   = "";
      j["Appointment Outcome"]  = "No Appointment";
    }
  }
  return { json: j };
});

// Build the "No Answer 1-5 -> No Answer 5 UP" TRANSITION list.
