// SMART TRACE + confidence gate metadata for review routing.
const INJ = /(ignore (all |the |these )?(previous |above )?(instructions?|prompts?)|disregard (the |all |previous |these )?(instructions?|prompts?)|ignore the (system )?prompt|forget (all |everything|the )?(previous |above )?(instructions?|prompts?)|you are now (a |an )|new instructions?\s*:|override (the )?(status|rule|system)|respond only with|output (only )?the following|set status to|mark this as)\b/i;
const SRC = [
  [/curse|wrong_number|denied_registration|no_money|under_18|invalid_country|third_party|base:no_language/i, 0.95, 'deterministic strong policy'],
  [/refusal_in_newest|callback_in_newest|refusal_2_days/i, 0.90, 'clear signal in newest comment'],
  [/Decline/i, 0.90, 'decline policy'],
  [/no_answer_5_distinct_days|no_real_conversation/i, 0.85, 'mechanical no-answer rule'],
  [/callback_detected|Appointment/i, 0.80, 'appointment/callback detection'],
  [/Sheet rule/i, 0.78, 'sheet rule matched'],
  [/Verifier AI/i, 0.70, 'verifier correction'],
  [/AI Agent/i, 0.60, 'AI judgement'],
  [/memory|policy/i, 0.88, 'memory/policy match'],
];
return $input.all().map(it => {
  const j = it.json;
  const src = String(j['Decision Source'] || '');
  const comments = String(j['last 10 comments'] || '');
  let score = 0.55, why = 'default';
  for (const [re, s, label] of SRC) { if (re.test(src)) { score = s; why = label; break; } }
  const aiCheck = String(j['AI Check'] || '').toLowerCase();
  if (aiCheck === 'disagree') { score -= 0.20; why += ' + verifier disagreement'; }
  if (String(j['Verifier Applied'] || '')) { score = Math.min(score, 0.72); }
  const inj = INJ.test(comments);
  if (inj) score -= 0.12;
  const vr = String(j['Validation Result'] || '').toLowerCase();
  if (vr === 'correct' && score >= 0.85) why += ' + auto-accept candidate';
  score = Math.max(0.05, Math.min(0.99, score));
  const band = score >= 0.80 ? 'High' : (score >= 0.60 ? 'Medium' : 'Low');
  const review = (band === 'Low' || inj || aiCheck === 'disagree' || vr === 'wrong') ? 'High' : (band === 'Medium' ? 'Medium' : 'Low');
  const autoAccept = (band === 'High' && !inj && aiCheck !== 'disagree' && vr === 'correct') ? 'Yes' : 'No';
  return { json: { ...j,
    'Confidence': band,
    'Confidence Score': Math.round(score * 100) / 100,
    'Confidence Reason': why,
    'Injection Flag': inj ? 'Yes' : 'No',
    'Review Priority': review,
    'Auto Accept': autoAccept,
  }};
});

