// Structured JSON repair (Instructor-like) + map batch outputs back to leads.
function extractJSON(text) {
  const t = String(text || "").trim();
  if (!t) return null;
  try { return JSON.parse(t); } catch (e) {}
  const fence = t.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fence) { try { return JSON.parse(fence[1]); } catch (e) {} }
  const arr = t.match(/\[[\s\S]*\]/);
  if (arr) { try { return JSON.parse(arr[0]); } catch (e) {} }
  const obj = t.match(/\{[\s\S]*\}/);
  if (obj) { try { return JSON.parse(obj[0]); } catch (e) {} }
  // trailing comma repair
  const cleaned = t.replace(/,\s*([}\]])/g, '$1');
  try { return JSON.parse(cleaned); } catch (e) {}
  if (arr) { try { return JSON.parse(arr[0].replace(/,\s*([}\]])/g, '$1')); } catch (e) {} }
  return null;
}

function asArray(parsed) {
  if (!parsed) return [];
  if (Array.isArray(parsed)) return parsed;
  if (Array.isArray(parsed.results)) return parsed.results;
  if (Array.isArray(parsed.leads)) return parsed.leads;
  if (parsed["account no"] != null) return [parsed];
  return [];
}

