Suggested: ${q.suggested || '-'} (${q.validation || '?'}, ${q.confidence || '?'})
Agent: ${q.agent || '-'}
Why: ${q.reason || '-'}
Comment: ${q.comments || '-'}

What should the status be? Tap one button:`;
  return {
    json: {
      chat_id: chatId,
      survey_text: text,
      account: q.account,
      _survey_index: i + 1,
      _survey_total: queue.length
    },
    // also pass markup fields for expression-based telegram node if needed
    reply_markup_rows: rows
  };
});

